import numpy as np
from scipy.signal import butter, savgol_filter, sosfiltfilt


def _median3(x):
    x = np.asarray(x, dtype=float)
    if x.size < 3:
        return x.copy()
    z = np.empty_like(x)
    z[0] = x[0]
    z[-1] = x[-1]
    z[1:-1] = np.median(np.stack((x[:-2], x[1:-1], x[2:]), axis=0), axis=0)
    return z


def _reflect_convolve(x, kernel):
    r = len(kernel) // 2
    if r == 0:
        return x.copy()
    xp = np.pad(x, (r, r), mode="reflect")
    return np.convolve(xp, kernel, mode="valid")


def _gaussian(sigma, radius):
    t = np.arange(-radius, radius + 1, dtype=float)
    k = np.exp(-0.5 * (t / sigma) ** 2)
    return k / np.sum(k)


def adaptive_filter(x, window_size=20):
    x = np.asarray(x, dtype=float)
    if len(x) < window_size:
        raise ValueError("input shorter than window")
    return np.convolve(x, np.ones(window_size) / window_size, mode="valid")


def enhanced_filter_with_trend_preservation(x, window_size=20):
    """Apply residual-gated narrow, moderate, and wide zero-phase filters."""
    x = np.asarray(x, dtype=float).copy()
    if len(x) < window_size:
        raise ValueError("input shorter than window")

    if not np.all(np.isfinite(x)):
        good = np.isfinite(x)
        if not np.any(good):
            x[:] = 0.0
        else:
            idx = np.arange(len(x))
            x = np.interp(idx, idx[good], x[good])

    n = len(x)
    if n == 0:
        return np.empty(0, dtype=float)

    # Robust narrow-band candidate: median preprocessing removes impulses,
    # while Savitzky-Golay interpolation preserves local curvature.
    robust = _median3(x)
    sg_window = min( nine := 9, n if n % 2 else n - 1)
    if sg_window < 3:
        narrow = robust.copy()
    else:
        narrow = savgol_filter(
            robust, sg_window, min(2, sg_window - 1), mode="interp"
        )

    # Three fixed zero-phase candidates provide local bandwidth choices
    # without introducing causal phase delay.
    def zero_phase(cutoff):
        """Design and apply a third-order zero-phase Butterworth filter."""
        sos = butter(3, cutoff, btype="lowpass", output="sos")
        try:
            return np.asarray(sosfiltfilt(sos, x, padtype="odd"), dtype=float)
        except ValueError:
            return np.asarray(sosfiltfilt(sos, x, padlen=max(1, n - 1)), dtype=float)

    moderate = zero_phase(0.16)
    wide = zero_phase(0.28)

    # Gate on robust nine-sample residual energy and five-sample slope
    # persistence.  The residual is median-filtered only for gate stability;
    # none of the selected signal candidates is median-flattened.
    residual = _median3(x - narrow)
    energy = np.convolve(
        residual * residual, np.ones(9, dtype=float) / 9.0, mode="same"
    )
    slope = np.diff(wide, prepend=wide[0])
    slope_sign = np.sign(slope)
    persistence = np.convolve(
        (slope_sign[1:] * slope_sign[:-1] > 0).astype(float),
        np.ones(5, dtype=float) / 5.0,
        mode="same",
    )
    persistence = np.pad(persistence, (1, 0), mode="edge")[:n]

    scale = 1.4826 * np.median(np.abs(residual - np.median(residual)))
    scale = max(float(scale), 1e-6)
    low_energy = energy <= (1.35 * scale) ** 2
    persistent_slope = persistence >= 0.60

    # Blend moderate and wide estimates in ambiguous regions.  Persistent
    # trends receive the wider candidate; quiet inconsistent regions receive
    # the narrow candidate to suppress spurious reversals.
    blend = np.clip(0.25 + 0.50 * persistence, 0.25, 0.75)
    mixed = blend * wide + (1.0 - blend) * moderate
    selected = np.where(low_energy & ~persistent_slope, narrow, mixed)
    selected = np.where(persistent_slope, wide, selected)

    return np.asarray(selected[window_size - 1:], dtype=float)


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    rng = np.random.RandomState(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(rng.randn(length) * 0.05)
    return clean_signal + rng.normal(0, noise_level, length), clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(
            signal_length, noise_level)
    else:
        noisy_signal = np.asarray(noisy_signal, dtype=float)
        clean_signal = None

    filtered = process_signal(noisy_signal, window_size, "enhanced")
    result = {
        "filtered_signal": filtered,
        "clean_signal": None,
        "noisy_signal": None,
        "correlation": 0,
        "noise_reduction": 0,
        "signal_length": len(filtered),
    }

    if clean_signal is not None:
        clean = clean_signal[window_size - 1:]
        noisy = noisy_signal[window_size - 1:]
        m = min(len(filtered), len(clean))
        filtered = filtered[:m]
        clean = clean[:m]
        noisy = noisy[:m]
        corr = np.corrcoef(filtered, clean)[0, 1] if m > 1 else 0.0
        before = np.var(noisy - clean)
        after = np.var(filtered - clean)
        result.update({
            "filtered_signal": filtered,
            "clean_signal": clean,
            "noisy_signal": noisy,
            "correlation": float(corr),
            "noise_reduction": float((before - after) / before)
                if before > 0 else 0.0,
            "signal_length": m,
        })
    return result


if __name__ == "__main__":
    r = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {r['correlation']:.3f}")
    print(f"Noise reduction: {r['noise_reduction']:.3f}")
    print(f"Processed signal length: {r['signal_length']}")
